#include <stdio.h>
#include <string.h>

// Global variables to mimic the original
char flag[100];
int index_flag = 0;

// Function to process a character and print its binary representation
void printbinchar(char c) {
    int bits[8] = {0};

    // Extract the bits
    for (int i = 0; i < 8; i++) {
        bits[i] = ((c << i) >> 7) & 1;
    }

    // Perform the xoring logic
    for (int i = 0; i < 4; i++) {
        if (bits[i] == bits[i+4]) {
            flag[index_flag] = '0';
        } else {
            flag[index_flag] = '1';
        }
        index_flag++;
    }
}

int main() {
    // The hardcoded string from the binary
    char str[] = "BgApYb7nCswD";
    int len = strlen(str);

    // Process characters at even indices (except 0)
    for (int i = 0; i < len; i++) {
        if ((i & 1) == 0 && i != 0) {
            printf("Processing character '%c' at index %d\n", str[i], i);
            printbinchar(str[i]);
        }
    }

    // Null-terminate the flag string
    flag[index_flag] = '\0';

    // Print the binary result
    printf("\nBinary result: %s\n", flag);

    // Convert binary to ASCII
    printf("\nConverting binary to ASCII:\n");
    for (int i = 0; i < index_flag; i += 8) {
        if (i + 8 <= index_flag) {
            int byte = 0;
            for (int j = 0; j < 8; j++) {
                byte = (byte << 1) | (flag[i + j] - '0');
            }
            printf("%c", byte);
        }
    }
    printf("\n");

    return 0;
}
